package mosse;

import java.util.ArrayList;
import java.util.List;

import org.junit.Test;

import beast.base.evolution.alignment.Alignment;
import beast.base.evolution.alignment.Sequence;
import beast.base.evolution.alignment.TaxonSet;
import beast.base.evolution.sitemodel.SiteModel;
import beast.base.evolution.substitutionmodel.Frequencies;
import beast.base.evolution.substitutionmodel.HKY;
import beast.base.evolution.substitutionmodel.JukesCantor;
import beast.base.evolution.tree.TraitSet;
import beast.base.evolution.tree.Tree;
import beast.base.inference.parameter.RealParameter;


/**
 * @author Thomas Wong
 */

public class MosseTreeLikelihoodReal88_3 {

    /**
     * returns an Alignment of nucleotide sequences
     * @param numLeaves number of taxa (or leaves in tree)
     * @param sequences nucleotide sequences for each taxa
     * @return an Alignment of nucleotide sequences
     */
    public Alignment getAlignment(int numLeaves, String[] sequences) {
        List<Sequence> seqList = new ArrayList<>();

        for (int i = 0; i < numLeaves; i++) {
            String taxonID = "t" + i;
            seqList.add(new Sequence(taxonID, sequences[i]));
        }

        Alignment alignment = new Alignment(seqList, "nucleotide");

        return alignment;
    }

    /**
     * returns an Alignment of nucleotide sequences
     * @param numLeaves number of taxa (or leaves in tree)
     * @param names taxa names
     * @param sequences nucleotide sequences for each taxa
     * @return an Alignment of nucleotide sequences
     */
    public Alignment getAlignment(int numLeaves, String[] names, String[] sequences) {
        List<Sequence> seqList = new ArrayList<>();

        assert names.length == sequences.length;
        for (int i = 0; i < numLeaves; i++) {
            seqList.add(new Sequence(names[i], sequences[i]));
        }

        Alignment alignment = new Alignment(seqList, "nucleotide");

        return alignment;
    }

    /**
     * tests initialization of MosseTreeLikelihood does not throw any errors
     * using a simple two taxa tree (t0: 0.5, t1: 0.5) with tips "A" and "C"
     */
    @Test
    public void testMosseLikelihood() {

    	long startTime = System.nanoTime();

        int numLeaves = 20;
        String[] names = {"sp1","sp2","sp3","sp4","sp5","sp6","sp7","sp8","sp9","sp10","sp11","sp12","sp13","sp14","sp15","sp16","sp17","sp18","sp19","sp20"};
        
        String[] sequences = {
        		
        		"a","a","g","g","g","a","a","g","g","g","a","a","a","a","a","g","g","g","a","a"
        		
        		/*
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		"",
        		""
        		*/
        };
        
        // real tree
        String newick = "(((sp1:1.136252742864,(sp6:0.370974278664,sp7:0.370974278664):0.7652784641999999):0.20328809250000002,((sp2:0.888610884764,(sp12:0.2058027804639999,(sp19:0.005169135363999988,sp20:0.005169135363999988):0.20063364509999992):0.6828081043):0.1829592832,(sp11:0.253933927164,(sp13:0.13135181666399998,(sp14:0.08930814299399992,sp15:0.08930814299399992):0.04204367367000006):0.12258211050000001):0.8176362408):0.2679706674):0.11088441410000005,((sp3:0.657865699264,sp4:0.657865699264):0.09768388859999999,(sp5:0.4341167922639999,((sp8:0.3173241429839999,sp9:0.3173241429839999):0.04132964525000005,(sp10:0.28876300602400007,(sp16:0.08237786712400008,(sp17:0.06969500930400008,sp18:0.06969500930400008):0.012682857820000004):0.2063851389):0.06989078220999989):0.07546300402999995):0.32143279560000004):0.6948756616):0.0;";
        
        String trait0Values = "sp1=0.0833467383343133,sp2=0.0824117591711532,sp3=0.0935280209974984,sp4=0.0611704285363165,sp5=0.122524532036765,sp6=0.10663627706989,sp7=0.103831197672974,sp8=0.106726366109762,sp9=0.0941371212229556,sp10=0.127201890030397,sp11=0.0653856806667778,sp12=0.0739509901654558,sp13=0.0566244363223972,sp14=0.0707056078670763,sp15=0.0660892297786694,sp16=0.116059399948816,sp17=0.106646719956241,sp18=0.108335264301845,sp19=0.0682102994057505,sp20=0.0680062882760867";

        int numTraits = 1;

        Alignment alignment = getAlignment(numLeaves, names, sequences);

        // Parameters
        Double[] betasArray = { 1.0 };
        double meanSubst = 0.015; // mean substitution rate
        double epsilon = 0.001;
        int numBins = 1024;

        // Parameters for lambda and mu functions
        Double[] y0 = new Double[] { 0.00001 };
        Double[] y1 = new Double[] { 2.25 }; // speciation rate
        Double[] r = new Double[] {  30.0 };
        Double[] yValue = new Double[] { 0.0046 }; // extinction rate

        // Parameters for Mosse distribution
        Double[] drift = new Double[] { 0.0 }; // drift parameter
        
        Double[] diffusion = new Double[] { 0.0005 }; // diffusion parameter
        double dt = 0.001;            // time interval dt
        int width = 5;
        int resolution = 4;

        Tree tree = new Tree(newick);

        // For HKY model
        RealParameter kappa = new RealParameter("45.5");
        RealParameter freqsParam = new RealParameter("0.1551 0.1501 0.526 0.1688");
        Frequencies freqs = new Frequencies();
        freqs.initByName("frequencies", freqsParam);
        HKY hky = new HKY();
        hky.initByName(
        		"kappa", kappa,
        		"frequencies", freqs
        );
        
        SiteModel siteModel = new SiteModel();
        siteModel.initByName(
                "mutationRate", "1.0",
                "gammaCategoryCount", "4",
                "shape", "20",
                "substModel", hky);

        MosseTipLikelihood tipModel = new MosseTipLikelihood();
        tipModel.initByName(
                "beta", new RealParameter(betasArray),
                "subst", Double.toString(meanSubst),
                "epsilon", Double.toString(epsilon),
                "logscale", "false"
        );

        // trait 0
        TraitSet trait0 = new TraitSet();
        trait0.initByName(
                "traitname", "trait0",
                "taxa", new TaxonSet(alignment),
                "value", trait0Values);
        List<TraitSet> traitsList = new ArrayList<>(numTraits);
        traitsList.add(trait0);

        RealParameter y0rp = new RealParameter(y0);
        RealParameter y1rp = new RealParameter(y1);
        RealParameter rrp = new RealParameter(r);
        LinearFunction logistFunc = new LinearFunction();
        logistFunc.initByName( "curveYBaseValue",
                y0rp, "curveMaxY", y1rp,
                "logisticGrowthRate", rrp);
        // constant
        RealParameter yValueRP = new RealParameter(yValue);
        ConstantLinkFn constFunc = new ConstantLinkFn();
        constFunc.initByName("yV", yValueRP);

        MosseDistribution mosseDist = new MosseDistribution();
        
        RealParameter driftrp = new RealParameter(drift);
        RealParameter diffusionrp = new RealParameter(diffusion);

        mosseDist.initByName(
                "tree", tree,
                "nx", Integer.toString(numBins),           // number of bins for substitution rate
                "drift", driftrp,           // drift parameter
                "diffusion", diffusionrp,   // diffusion parameter
                "dt", Double.toString(dt),                 // time interval dt
                "width", Integer.toString(width),
                "resolution", Integer.toString(resolution),
                "threads", 16                               // number of cpu threads
        );

        MosseTreeLikelihood likelihood = new MosseTreeLikelihood();
        likelihood.initByName(
                "data", alignment,
                "tree", tree,
                "siteModel", siteModel,
                "tipModel", tipModel,
                "treeModel", mosseDist,
                "traits", traitsList,
                "lambdaFunc", logistFunc,
                "muFunc", constFunc
                );

        // using observed root
        double result = likelihood.calculateLogP();
        System.out.println("testMosseLikelihood logP = " + result);

    	long endTime = System.nanoTime();
    	long durationInNano = endTime - startTime;
    	long durationInMillis = durationInNano / 1_000_000;
    	long durationInSec = durationInMillis / 1000;

    	System.out.println("Execution time: " + durationInSec + " seconds");

    	Runtime runtime = Runtime.getRuntime();

    	long totalMemory = runtime.totalMemory(); // Total memory currently available to the JVM
    	long freeMemory = runtime.freeMemory();   // Free memory within the JVM
    	long usedMemory = totalMemory - freeMemory; // Memory currently in use by the JVM

    	System.out.println("Total JVM Memory: " + totalMemory / (1024 * 1024) + " MB");
    	System.out.println("Free JVM Memory: " + freeMemory / (1024 * 1024) + " MB");
    	System.out.println("Used JVM Memory: " + usedMemory / (1024 * 1024) + " MB");
    }
}
